document.querySelector('#send-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=document.querySelector('#send-button'),s=document.querySelector('#send-status'),data=new FormData(f),file=data.get('file');if(!String(data.get('body')).trim()&&!file?.size){s.textContent='Cole o texto do sermão ou anexe um arquivo.';return}if(file?.size>10*1024*1024){s.textContent='O arquivo deve ter no máximo 10 MB.';return}b.disabled=true;s.textContent='Enviando seu material…';try{const r=await fetch('/api/submissions',{method:'POST',body:data}),v=await r.json();if(!r.ok)throw Error(v.error);f.reset();s.textContent='Material recebido! A equipe já pode revisá-lo no painel. Protocolo: '+v.id;s.className='success';}catch(err){s.textContent=err.message||'Não foi possível enviar. Tente novamente.';s.className='error'}finally{b.disabled=false}};
